jQuery(document).ready(function(){
  jQuery(".related-fullwidth.featured-posts .open-more").click(function(){
    jQuery(".related-fullwidth.featured-posts .col3:nth-child(n+5)").slideToggle();
    jQuery(".related-fullwidth.featured-posts .col12 h4").text(jQuery(".related-fullwidth.featured-posts .col12 h4").text() == 'Prikaži manje' ? 'Prikaži više' : 'Prikaži manje');
    jQuery(".related-fullwidth.featured-posts .col12 i").toggleClass('fa-chevron-up');
  });
});//ready

	jQuery(document).ready(function(){
		jQuery('.featured-post').next('.featured-posts').remove();
	});
